.page-header .eyebrow {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(91,94,244,.08);
  padding: 4px 10px;
  border-radius: 20px;
  margin-bottom: 12px;
}

.page-header h1 {
  font-size: clamp(22px, 4vw, 30px);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.25;
  margin-bottom: 8px;
}

.page-header p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ── Quiz card ── */
.quiz-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  width: 100%;
  max-width: 560px;
  padding: 32px;
}

/* ── Progress bar ── */
.progress-bar-wrap {
  margin-bottom: 28px;
}

.progress-meta {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 8px;
  font-weight: 500;
}

.progress-track {
  height: 4px;
  background: var(--border);
  border-radius: 99px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), #8b8ef8);
  border-radius: 99px;
  transition: width .5s ease;
}

/* ── Form fields ── */
.form-field {
  padding: 24px 0;
  border-bottom: 1px solid var(--border);
}

.form-field:last-of-type {
  border-bottom: none;
  padding-bottom: 0;
}

.form-field:first-of-type {
  padding-top: 0;
}

.question-number {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 6px;
}

.question-label {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 6px;
  color: var(--text-primary);
}

.help-text {
  font-size: 13px;
  color: var(--text-help);
  margin-bottom: 16px;
  line-height: 1.5;
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.help-text svg {
  flex-shrink: 0;
  margin-top: 1px;
}

.choices {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 14px;
  list-style: none;
}

/* ── Checkbox option ── */
.choice-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: border-color .15s, background .15s, box-shadow .15s;
  user-select: none;
  position: relative;
}

.choice-item:hover {
  border-color: var(--accent);
  background: rgba(91,94,244,.03);
}

.choice-item:has(input:checked) {
  border-color: var(--accent);
  background: rgba(91,94,244,.05);
}

.choice-item:focus-within {
  box-shadow: 0 0 0 3px rgba(91,94,244,.2);
  border-color: var(--accent);
  outline: none;
}

.choice-item input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--check-border);
  border-radius: 5px;
  background: #fff;
  cursor: pointer;
  flex-shrink: 0;
  position: relative;
  transition: border-color .15s, background .15s;
}

.choice-item input[type="checkbox"]:checked {
  background: var(--check-bg);
  border-color: var(--check-bg);
}

.choice-item input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  left: 4px;
  top: 1.5px;
  width: 6px;
  height: 10px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

.choice-item input[type="checkbox"]:focus-visible {
  outline: none;
}

.choice-text {
  font-size: 14.5px;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.4;
  flex: 1;
}

.choice-badge {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 2px 7px;
  flex-shrink: 0;
  transition: background .15s, color .15s;
}

.choice-item:has(input:checked) .choice-badge {
  background: rgba(91,94,244,.12);
  color: var(--accent);
  border-color: rgba(91,94,244,.2);
}

/* ── Submit area ── */
.submit-area {
  margin-top: 28px;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 12px;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--accent);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  padding: 14px 24px;
  cursor: pointer;
  box-shadow: var(--shadow-btn);
  transition: background .15s, transform .1s, box-shadow .15s;
}

.btn-submit:hover {
  background: var(--accent-hover);
  box-shadow: 0 2px 4px rgba(91,94,244,.3), 0 8px 20px rgba(91,94,244,.25);
}

.btn-submit:active {
  transform: scale(.98);
}

.btn-submit:focus-visible {
  outline: 3px solid rgba(91,94,244,.4);
  outline-offset: 2px;
}

.hint-text {
  font-size: 12px;
  color: var(--text-help);
  text-align: center;
}

/* ── Result banner ── */
.result-banner {
  display: none;
  align-items: center;
  gap: 14px;
  padding: 16px 20px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  margin-top: 20px;
  border: 1.5px solid transparent;
}

.result-banner.show {
  display: flex;
}

.result-banner.pass {
  background: rgba(34,197,94,.07);
  border-color: rgba(34,197,94,.25);
  color: #15803d;
}

.result-banner.fail {
  background: rgba(239,68,68,.06);
  border-color: rgba(239,68,68,.2);
  color: #b91c1c;
}

.result-icon {
  font-size: 22px;
  flex-shrink: 0;
}

.result-banner strong {
  display: block;
  font-size: 15px;
  margin-bottom: 2px;
}

/* ── Correct / incorrect answer highlighting ── */
.choice-item.correct {
  border-color: #22c55e !important;
  background: rgba(34,197,94,.06) !important;
}

.choice-item.incorrect {
  border-color: #ef4444 !important;
  background: rgba(239,68,68,.05) !important;
}

.choice-item.missed {
  border-color: #f59e0b !important;
  background: rgba(245,158,11,.05) !important;
}

.choice-item.locked {
  cursor: default;
  pointer-events: none;
}

/* ── Responsive ── */
@media (max-width: 480px) {
  .quiz-card {
    padding: 24px 18px;
  }
}
