  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--check-border);
  border-radius: 5px;
  background: #fff;
  cursor: pointer;
  flex-shrink: 0;
  position: relative;
  transition: border-color .15s, background .15s;
}

.choice-item input[type="checkbox"]:checked {
  background: var(--check-bg);
  border-color: var(--check-bg);
}

.choice-item input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  left: 4px;
  top: 1.5px;
  width: 6px;
  height: 10px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

.choice-item input[type="checkbox"]:focus-visible {
  outline: none;
}

.choice-text {
  font-size: 14.5px;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.4;
  flex: 1;
}

.choice-badge {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 2px 7px;
  flex-shrink: 0;
  transition: background .15s, color .15s;
}

.choice-item:has(input:checked) .choice-badge {
  background: rgba(91,94,244,.12);
  color: var(--accent);
  border-color: rgba(91,94,244,.2);
}

