+const QUESTIONS = [
+  {
+    id: "q1",
+    number: "Question 1 of 3",
+    text: "Which of the following are statically typed programming languages?",
+    helpText: "Statically typed languages check types at compile time rather than at runtime.",
+    choices: [
+      { id: "q1a", label: "TypeScript", letter: "A" },
+      { id: "q1b", label: "Python",     letter: "B" },
+      { id: "q1c", label: "Java",       letter: "C" },
+      { id: "q1d", label: "Ruby",       letter: "D" },
+    ],
+    correct: new Set(["q1a", "q1c"]),
+  },
+  {
+    id: "q2",
+    number: "Question 2 of 3",
+    text: "Which languages were originally designed for web browsers?",
+    helpText: null,
+    choices: [
+      { id: "q2a", label: "JavaScript",  letter: "A" },
+      { id: "q2b", label: "C++",         letter: "B" },
+      { id: "q2c", label: "WebAssembly", letter: "C" },
+      { id: "q2d", label: "Rust",        letter: "D" },
+    ],
+    correct: new Set(["q2a", "q2c"]),
+  },
+  {
+    id: "q3",
+    number: "Question 3 of 3",
+    text: "Which of the following languages support first-class functions?",
+    helpText: null,
+    choices: [
+      { id: "q3a", label: "Haskell",    letter: "A" },
+      { id: "q3b", label: "JavaScript", letter: "B" },
+      { id: "q3c", label: "COBOL",      letter: "C" },
+      { id: "q3d", label: "Python",     letter: "D" },
+    ],
+    correct: new Set(["q3a", "q3b", "q3d"]),
+  },
+];
+
+/* ── State ── */
+const state = {
+  answers: { q1: new Set(), q2: new Set(), q3: new Set() },
+  submitted: false,
+};
+
+/* ── Helpers ── */
+function $(sel) { return document.querySelector(sel); }
+function $$(sel) { return document.querySelectorAll(sel); }
+
+/* ── Render questions ── */
+function renderQuestions() {
+  const form = $("#quiz-form");
+
+  QUESTIONS.forEach((q) => {
+    const field = document.createElement("div");
+    field.className = "form-field";
+    field.setAttribute("role", "group");
+    field.setAttribute("aria-labelledby", `${q.id}-label`);
+
+    const numEl = document.createElement("p");
+    numEl.className = "question-number";
+    numEl.setAttribute("aria-hidden", "true");
+    numEl.textContent = q.number;
+
+    const labelEl = document.createElement("p");
+    labelEl.className = "question-label";
+    labelEl.id = `${q.id}-label`;
+    labelEl.textContent = q.text;
+
+    field.appendChild(numEl);
+    field.appendChild(labelEl);
+
+    if (q.helpText) {
+      const help = document.createElement("p");
+      help.className = "help-text";
+      help.id = `${q.id}-help`;
+      help.innerHTML = `
+        <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
+          <circle cx="8" cy="8" r="7" stroke="#8891a4" stroke-width="1.5"/>
+          <path d="M8 7v5" stroke="#8891a4" stroke-width="1.5" stroke-linecap="round"/>
+          <circle cx="8" cy="4.5" r=".75" fill="#8891a4"/>
+        </svg>
+        ${q.helpText}`;
+      field.appendChild(help);
+    }
+
+    const list = document.createElement("ul");
+    list.className = "choices";
+    list.setAttribute("aria-label", "Answer choices");
+
+    q.choices.forEach((c) => {
+      const li = document.createElement("li");
+
+      const lbl = document.createElement("label");
+      lbl.className = "choice-item";
+      lbl.htmlFor = c.id;
+
+      const cb = document.createElement("input");
+      cb.type = "checkbox";
+      cb.id = c.id;
+      cb.name = q.id;
+      cb.value = c.id;
+      if (q.helpText) cb.setAttribute("aria-describedby", `${q.id}-help`);
+
+      cb.addEventListener("change", () => {
+        if (state.submitted) return;
+        if (cb.checked) {
+          state.answers[q.id].add(c.id);
+        } else {
+          state.answers[q.id].delete(c.id);
+        }
+        updateProgress();
+      });
+
+      const badge = document.createElement("span");
+      badge.className = "choice-badge";
+      badge.setAttribute("aria-hidden", "true");
+      badge.textContent = c.letter;
+
+      const text = document.createElement("span");
+      text.className = "choice-text";
+      text.textContent = c.label;
+
+      lbl.appendChild(cb);
+      lbl.appendChild(badge);
+      lbl.appendChild(text);
+      li.appendChild(lbl);
+      list.appendChild(li);
+    });
+
+    field.appendChild(list);
+    form.insertBefore(field, form.querySelector(".submit-area"));
+  });
+}
+
+/* ── Progress bar ── */
+function updateProgress() {
+  const answered = QUESTIONS.filter((q) => state.answers[q.id].size > 0).length;
+  const pct = Math.round((answered / QUESTIONS.length) * 100);
+  $(".progress-fill").style.width = `${pct}%`;
+  $(".progress-meta .answered").textContent = `${answered} / ${QUESTIONS.length} answered`;
+}
+
+/* ── Submit ── */
+function handleSubmit(e) {
+  e.preventDefault();
+  if (state.submitted) return;
+
+  const unanswered = QUESTIONS.filter((q) => state.answers[q.id].size === 0);
+  if (unanswered.length > 0) {
+    const first = unanswered[0];
+    const el = document.getElementById(`${first.id}-label`);
+    el && el.scrollIntoView({ behavior: "smooth", block: "center" });
+    el && el.focus({ preventScroll: true });
+    showValidationHint(unanswered.length);
+    return;
+  }
+
+  state.submitted = true;
+
+  let score = 0;
+
+  QUESTIONS.forEach((q) => {
+    const selected = state.answers[q.id];
+
+    q.choices.forEach((c) => {
+      const lbl = document.querySelector(`label[for="${c.id}"]`);
+      lbl.classList.add("locked");
+
+      const isSelected = selected.has(c.id);
+      const isCorrect  = q.correct.has(c.id);
+
+      if (isSelected && isCorrect)  lbl.classList.add("correct");
+      if (isSelected && !isCorrect) lbl.classList.add("incorrect");
+      if (!isSelected && isCorrect) lbl.classList.add("missed");
+    });
+
+    const questionCorrect =
+      selected.size === q.correct.size &&
+      [...selected].every((id) => q.correct.has(id));
+
+    if (questionCorrect) score++;
+  });
+
+  showResult(score);
+  $(".btn-submit").disabled = true;
+  $(".hint-text").textContent = "Quiz submitted — see your results below.";
+}
+
+function showValidationHint(count) {
+  const hint = $(".hint-text");
+  hint.style.color = "#ef4444";
+  hint.textContent = `Please answer ${count} remaining question${count > 1 ? "s" : ""} before submitting.`;
+  setTimeout(() => {
+    hint.style.color = "";
+    hint.textContent = "Select all answers that apply, then submit.";
+  }, 3000);
+}
+
+function showResult(score) {
+  const banner = $(".result-banner");
+  const total  = QUESTIONS.length;
+  const pass   = score === total;
+
+  banner.classList.add("show", pass ? "pass" : "fail");
+  banner.querySelector(".result-icon").textContent = pass ? "🎉" : "📝";
+  banner.querySelector(".result-message").innerHTML = `
+    <strong>${score} / ${total} correct</strong>
+    ${pass
+      ? "Perfect score! You really know your programming languages."
+      : "Good try! Review the highlighted answers to see what you missed."}
+  `;
+  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
+  banner.setAttribute("aria-live", "polite");
+}
+
+/* ── Init ── */
+document.addEventListener("DOMContentLoaded", () => {
+  renderQuestions();
+  updateProgress();
+  $("#quiz-form").addEventListener("submit", handleSubmit);
+});
+
')

